INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66521321', 66521321, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Junior Kurasi Data Perencanaan Pembangunan', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 99900000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Ruang lingkup pelaksanaan kegiatan Kurasi Data Perencanaan Pembangunan adalah menyiapkan dokumen kurasi data yang mencakup inventarisasi, verifikasi kualitas data, standarisasi struktur data, harmonisasi metadata, serta penyelarasan kode referensi dan data induk di Kementerian PPN/Bappenas. Kegiatan ini mencakup pendampingan teknis, pemeriksaan kualitas data, analisis kebutuhan data untuk perencanaan, serta penyusunan rekomendasi perbaikan tata kelola data. Pelaksanaan kegiatan mengacu pada Peraturan Presiden Nomor 39 Tahun 2019 tentang Satu Data Indonesia, Peraturan Menteri Komunikasi dan Informatika Nomor 1 Tahun 2023 tentang Interoperabilitas Data, dan ketentuan manajemen data lainnya yang berlaku dalam penyelenggaraan SPBE.', 'a. Pendidikan minimal S1 dari institusi terakreditasi pada bidang teknik informatika, sistem informasi, statistika, atau bidang terkait pengelolaan data, dibuktikan dengan sertifikat. b. Memiliki pengalaman pada bidang teknik informatika, sistem informasi, statistika, atau bidang terkait pengelolaan data minimal 2 tahun dibuktikan dengan bukti kontrak pekerjaan sebelumnya/surat referensi/surat keterangan kerja. c. Memiliki kemampuan dalam pengolahan, pemeriksaan kualitas, dan analisis data menggunakan alat seperti SQL, Python, atau R, dibuktikan dengan sertifikat atau laporan hasil kerja. d. Memiliki pemahaman terhadap arsitektur dan siklus hidup data, termasuk metadata, struktur data terstandar, kode referensi, dan data induk, dibuktikan dengan laporan hasil kerja. e. Memiliki keahlian dalam menerapkan standar interoperabilitas data sesuai ketentuan Satu Data Indonesia dan SPBE, dibuktikan dengan laporan hasil kerja. f. Memiliki sertifikasi atau pelatihan di bidang data, seperti data governance, metadata management, atau data quality, dibuktikan dengan sertifikat. g. Memiliki pemahaman terkini mengenai tata kelola manajemen data, termasuk prinsip kualitas data, keamanan data, dan standarisasi data, dibuktikan dengan laporan hasil kerja. h. Pengalaman bekerja dalam tim dan berkoordinasi lintas unit atau lintas Kementerian/Lembaga, khususnya dalam harmonisasi dan standarisasi data, dibuktikan dengan bukti kontrak pekerjaan sebelumnya/surat referensi/surat keterangan kerja', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2832070);
