INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66523392', 66523392, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN INDIVIDUAL PENYUSUNAN KAJIAN ANALISIS PENGELOLAAN KEUANGAN HIBAHUNTUK PROYEK GEF SUSTAINABLE CITIES IMPACT PROGRAM (SCIP) LINGKUP DIREKTORATKEHUTANAN DAN KONSERVASI SUMBER DAYA AIR', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 160000000, 'April 2026', 'APBN - HIBAH LUAR NEGERI (I)', 1, 1, '1 Paket', 'Berikut tahapan pelaksanaan pekerjaan Jasa Konsultan Individual Penyusunan Kajian AnalisisPengelolaan Keuangan Hibah untuk Proyek GEF SCIP Komponen 2, yaitu: 1. Menyusun laporankeuangan yang berisikan database administrasi pengelolaan keuangan pelaksanaan kegiatanKomponen 2 lingkup lanskap berkelanjutan di 3 kota percontohan seperti kemajuan transaksipengeluaran, kemajuan realisasi, pemutakhiran/revisi anggaran setiap bulan. 2. Dokumenadministrasi dan keuangan (berkas pertanggungjawaban kegiatan, kontrak, AWP/annual workplan,OWP/overall workplan, dll) dari pelaksanaan kegiatan Komponen 2 lingkup lanskap berkelanjutandi kota percontohan dan pelaksanaan kegiatan komponen lainnya lingkup hibah GEF SCIP.', 'a. Memiliki pendidikan minimal D3 jurusan Kesekretariatan/Ekonomi; b. Memiliki pengalamankerja di bidang terkait dengan administrasi dan pengelolaan keuangan hibah paling kurang 1 (satu)pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupunswasta, termasuk pengalaman subkontrak dibuktikan dengan data pada CV dan dokumen lain yangsetara. c. Memiliki pengalaman kerja terkait dokumentasi administrasi keuangan hibah minimal 3tahun pengalaman dibuktikan dengan data pada CV dan dokumen lain yang setara. d. Nilaipekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang samadengan 50% (lima puluh persen) nilai HPS/Pagu Anggaran yang dibuktikan dengan data pada CVdan dokumen kontrak kerja.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2833563);
