INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66523737', 66523737, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN PENYUSUNAN REKOMENDASI STRATEGI AKSELERASI PDB  MARITIM  KEGIATAN ANALISIS KEBIJAKAN DAN STRATEGI MENCAPAI TARGET PDB  MARITIM 15 PERSEN PADA TAHUN 2045', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 130000000, 'April 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Analisis pertumbuhan ekonomi Indonesia berdasarkan Produk Domestik Bruto (PDB) dan PDB Maritim dalam dokumen perencanaan nasional 2. Analisis Kontribusi dan capaian ekonomi PDB maritim terhadap PDB nasional menurut indikator pendukung PDB maritim mencakup sektor-sektor ekonomi kemaritiman eksisting dan emerging 3. Analisis hilirisasi program ekonomi biru dalam mendorong akselerasi PDB Maritim menurut klaster utama 4. Penyusunan laporan analisis kebijakan dan strategi mencapai target PDB Maritim 15 Persen', '1. Memiliki pendidikan S2 dengan latar belakang manajemen/bisnis/ekonomi, diutamakan konsentrasi bidang kelautan dan perikanan; 2. Memiliki pengalaman kerja minimal 7 (tujuh) tahun secara keseluruhan dan 5 (tiga) tahun dalam bidang kelautan dan perikanan, dibuktikan dalam riwayat hidup/CV dan/atau kontrak kerja; 3. Memiliki nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu Anggaran; 4. Memiliki pemahaman terkait dalam analisis data kualitatif dan kuantitatif bidang kelautan dan perikanan; 5. Memiliki pemahaman terkait Rencana Pembangunan Jangka Menengah Nasional (RPJMN) dan dokumen Rencana Kerja Pemerintah (RKP) bidang kelautan dan perikanan menjadi nilai tambah; dan 6. Mempunyai sertifikat keahlian/teknis, dan/atau sertifikat pelatihan/kursus terkait sektor kelautan dan perikanan menjadi nilai tambah.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2834734);
