INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66523519', 66523519, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN PENYUSUNAN KAJIAN ANALISIS PELAKSANAAN PROYEK GEF SUSTAINABLE CITIESIMPACT PROGRAM (SCIP) BIDANG LANSKAP PERKOTAAN BERKELANJUTAN', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 192000000, 'April 2026', 'APBN - HIBAH LUAR NEGERI (I)', 1, 1, '1 Paket', 'Berikut tahapan pelaksanaan pekerjaan Tenaga Konsultan Penyusunan Kajian Analisis PelaksanaanProyek GEF SCIP Bidang Lanskap Perkotaan Berkelanjutan di Direktorat Kehutanan dan KonservasiSumber Daya Air, yaitu: 1. Melakukan pengumpulan data dan informasi terkait bidang lanskapperkotaan berkelanjutan di 5 kota percontohan GEF SCIP. 2. Melakukan analisis potensipengembangan lanskap perkotaan berkelanjutan di 5 kota percontohan GEF SCIP. 3. Melakukanpemetaan stakeholder terkait bidang lanskap perkotaan berkelanjutan di 5 kota percontohan GEFSCIP. 4. Melakukan reviu/telaah kemajuan pelaksanaan penyusunan dokumen tata kelolainfrastruktur dasar bidang lanskap perkotaan berkelanjutan untuk sub proyek di Kota Palembangdan Kota Jakarta. 5', 'a. Memiliki pendidikan minimal S1 jurusan Perencanaan Wilayah dan Kota/IlmuLingkungan/Ekonomi yang dibuktikan dengan ijazah; b. Memiliki pengalaman kerja minimal 3 (tiga)tahun di bidang perencanaan, analisis pembangunan perkotaan, dan/atau lanskap berkelanjutandengan proyek-proyek yang didanai oleh pemerintah atau donor yang dibuktikan dengan datapada CV atau dokumen lain yang setara. c. Memiliki pengalaman kerja terkait pengumpulan data,pemetaan stakeholder, penyusunan kesiapan proyek, serta pemantauan dan evaluasi di bidanglanskap berkelanjutan yang dibuktikan dengan data pada CV dan dokumen lain yang setara. d.Memiliki kemampuan dalam berbahasa Inggris baik lisan maupun tulisan yang dibuktikan dengansertifikat kemampuan Bahasa Inggris atau dokumen lain yang setara, termasuk publikasi ataulaporan dari studi/kajian/pekerjaan yang telah dilakukan. e. Nilai pekerjaan sejenis tertinggi dalamkurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilaiHPS/Pagu Anggaran yang dibuktikan dengan data pada CV dan dokumen kontrak kerja.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2835060);
