INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66523928', 66523928, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Penyusunan Kajian Analisis Penguatan Ketahanan Iklim Perkotaan', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 240000000, 'April 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket Dokumen', 'pengembangan dan/atau penguatan kebijakan ketahanan iklim di wilayah perkotaan untuk mendorong implementasi serta pencapaian target PBI', '1. Pendidikan minimal magister (S-2) di bidang Lingkungan/Kesehatan Lingkungan/Kesehatan Masyarakat; 2. Memiliki pengalaman kerja minimal 9 (sembilan) tahun; 3. Memiliki pengalaman kerja yang relevan dengan Pembangunan Berketahanan Iklim minimal 3 (tiga) tahun; 4. Berpengalaman di bidang ketahanan iklim dan pembangunan, khususnya pada sektor prioritas dalam Kebijakan Pembangunan Berketahanan Iklim, dibuktikan melalui pengalaman pada kontrak kerja/referensi kerja; 5. Memiliki pengalaman dalam mengelola kegiatan pemerintah, lembaga donor, NGO, atau mitra pembangunan, dibuktikan dengan pengalaman kerja pada kontrak kerja/referensi kerja; 6. Memiliki pengetahuan dan/atau pengalaman dalam proses perencanaan pembangunan, sistem pemerintahan, dan/atau hierarki peraturan perundang-undangan, terutama yang terkait dengan Pembangunan Berketahanan Iklim dibuktikan dengan pengalaman kerja pada kontrak kerja/referensi kerja; 7. Memiliki kemampuan menulis yang berkaitan dengan isu sektor Pembangunan Berketahanan Iklim atau lingkungan yang dibuktikan dengan hasil tulisan berupa artikel yang dipublikasikan di jurnal/prosiding/paper/artikel/media; 8. Memiliki sertifikat pelatihan Penyusunan Analisis Mengenai Dampak Lingkungan (AMDAL) yang dibuktikan dengan sertifikat resmi bernomor registrasi sebagai bukti terdaftar pada instansi pemerintah yang berwenang di bidang lingkungan hidup', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2835353);
