INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66524728', 66524728, 'analyze_legacy', 'Kementerian Koordinator Bidang Pembangunan Manusia dan Kebudayaan', 'central', 'KEMENKO BIDANG PEMBANGUNAN MANUSIA DAN KEBUDAYAAN', 'WA.6336.ABL.003.102.0A. Jasa Konsultan Perorangan Penyusunan Policy Brief Optimalisasi Peran Budaya Kerja dalam Peningkatan Kinerja Aparatur Pemerintah', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 66828000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Biaya Personil (Pendidikan S2 Minimal Pengalaman 10 Tahun) ( 60, OH, @ 800000 ); 2. Komputer Supplies ( 1, PKT, @ 714000 ); 3. Penggandaan dan Pencetakan Laporan ( 2, PKT, @ 550000 ); 4. ATK ( 2, PKT, @ 550000 ); 5. penyesuaian akun ( 1, 1, @ 15914000 );', 'Jasa Konsultan Perorangan (Pendidikan S2 Minimal Pengalaman 10 Tahun)', 15914000, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 2835356);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66523817', 66523817, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN PENYUSUNAN POLICY BRIEF POTENSI BIOEKONOMI DALAM PERTUMBUHAN EKONOMI INDONESIA DALAM RANGKA PENYUSUNAN  RENCANA STRATEGIS BIOEKONOMI INDONESIA DIREKTORAT KEHUTANAN DAN KONSERVASI SUMBER DAYA AIR', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 158000000, 'April 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Menyusun rencana kerja penyusunan rencana strategis bioekonomi indonesia. 2. Melakukan studi literatur, pengumpulan, pengelolaan data potensi ekonomi untuk pengembangan produk berbasis bioekonomi. 3. Melakukan studi literatur, pengumpulan, pengelolaan data untuk penyusunan kebijakan rencana strategis bioekonomi Indonesia. 4. Membantu menyiapkan kegiatan pendukung dalam rangka penyusunan rencana strategis bioekonomi Indonesia. 5. Membantu dalam mengkoordinasikan substansi sekaligus kegiatan yang berkaitan dengan penyusunan rencana strategis bioekonomi Indonesia. 6. Menyusun KAK dan bahan paparan untuk kegiatan rapat koordinasi, FGD, dan lokakarya yang berkaitan dengan konteks bioekonomi, ketahanan pangan, energi, dan air 7. Mengikuti kegiatan di lingkup Direktorat Kehutanan dan Konservasi Sumber Daya Air yang berkaitan dengan penyusunan rencana strategis bioekonomi Indonesia.', 'a. Memiliki pendidikan minimal Sarjana (S1) bidang ekonomi; b. Memiliki pengalaman kerja di bidang yang terkait dengan perencanaan pembangunan atau penyusunan rencana strategis pemerintahan di tingkat pusat atau daerah minimal 3 tahun yang dibuktikan dengan surat kontrak kerja sebelumnya; c. Mampu berpikir kritis dan analitis (minimal berpengalaman menggunakan 1 metode analisis perencanaan kuantitatif dan/atau 1 metode analisis perencanaan kuantitatif) d. Memiliki kemampuan menulis narasi dokumen/laporan dengan baik, dibuktikan dengan dokumen pekerjaan sebelumnya e. Memiliki pengetahuan desain dokumen/laporan dan paparan yang baik dokumen pekerjaan sebelumnya f. Memiliki kemampuan dalam melakukan analisis regulasi yang baik dokumen hasil pekerjaan sebelumnya g. Memiliki keahlian mengolah data dengan tools STATA/SPSS/aplikasi pengolahan data sejenis dokumen pekerjaan sebelumnya h. Memiliki pengetahuan atas analisis Input-Output (I-O) dan Social Accounting Matrix (SAM) menjadi nilai tambah i. Nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu Anggaran yang dibuktikan dengan data pada CV dan dokumen lain yang setara.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2835357);
