INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66523923', 66523923, 'analyze_legacy', 'Kota Gunungsitoli', 'kabkota', 'BADAN PERENCANAAN PEMBANGUNAN, RISET DAN INOVASI DAERAH KOTA GUNUNGSITOLI', 'Belanja Alat/Bahan untuk Kegiatan Kantor-Alat/Bahan untuk Kegiatan Kantor Lainnya', 'Barang', 'Pengadaan Langsung', 'Sumatera Utara, Gunung Sitoli (Kota)', 5594400, 'January 2026', 'APBD', 1, 1, '1 Paket', 'Alat/Bahan untuk Kegiatan Kantor Lainnya;', 'Cetak Spanduk, Digital;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2835361);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66523898', 66523898, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Penyusunan Kajian Prognosis Pelaksanaan Rencana Kerja Pembangunan & Pelaksanaan Tujuan Pembangunan Berkelanjutan Tahun 2026', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 109263000, 'April 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket Dokumen', 'Jasa Konsultan Penyusunan Kajian Prognosis Pelaksanaan Rencana Kerja Pembangunan & Pelaksanaan Tujuan Pembangunan Berkelanjutan Tahun 2026 adalah untuk memberikan dukungan teknis kepada Direktorat Lingkungan Hidup, Kementerian PPN/Bappenas dalam proses pengumpulan dan pengolahan data, analisis capaian, serta identifikasi hambatan dalam pelaksanaan Rencana Kerja Pembangunan Bidang Lingkungan Hidup Tahun 2026 dan analisis ketercapaian pelaksanaan Rencana Kerja Pembangunan Bidang Lingkungan Hidup Tahun 2025', '1. Pendidikan minimal magister (S-2) di bidang Manajemen Lingkungan/Sumber Daya Alam atau Ilmu Lingkungan; 2. Memiliki kompetensi sesuai bidang yang dipersyaratkan dibuktikan dengan ijazah jenjang pendidikan, sertifikat keahlian/teknis, dan/atau sertifikat pelatihan/kursus; 3. Memiliki kemampuan berbahasa Inggris yang dibuktikan dengan sertifikat kemampuan bahasa Inggris yang masih aktif dengan skor minimal setara dengan TOEFL iBT 94; PTE Academic 65; atau IELTS 7,0. 4. Memiliki pengalaman kerja 3 (tiga) tahun yang mendukung pembangunan berkelanjutan; 5. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 3 (tiga) tahun terakhir yang mendukung pelaksanaan pada bidang perencanaan/ rencana kerja/ rencana penganggaran dengan melampirkan referensi pengalaman kerja atau penelitian di bidang tersebut; 6. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 2 (dua) tahun terakhir baik di lingkungan pemerintah, dibuktikan dengan referensi/kontrak kerja; 7. Memiliki pengalaman paling kurang 1 (satu) pekerjaan sejenis dalam kurun waktu 3 (tiga) tahun (jenis pekerjaan, kompleksitas pekerjaan, metodologi, atau karakteristik lainnya yang bisa menggambarkan kesamaan); Memiliki keterampilan dalam analisis data, baik tabular maupun spasial, serta cakap dalam presentasi dan penulisan laporan dibuktikan melalui pengalaman kerja yang tercantum dalam referensi/kontrak kerja; 8. Memiliki kemampuan dan pengalaman dalam mengumpulkan dan mengolah data yang dihasilkan dari kegiatan Focus Group Discussion (FGD) dibuktikan melalui pengalaman kerja yang tercantum dalam referensi/kontrak kerja; 9. Memiliki pemahaman serta pengalaman terhadap sistem dan proses perencanaan pembangunan nasional, khususnya di bidang lingkungan hidup dibuktikan melalui pengalaman kerja yang tercantum dalam referensi/kontrak kerja; 10. Memiliki kemampuan menulis yang ditunjukkan dengan hasil tulisan berupa artikel yang dipublikasikan di jurnal/prosiding/paper yang berkaitan dengan lingkungan atau sumber daya alam.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2835362);
