INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66523934', 66523934, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Penyusunan Kajian Pengembangan Penilaian Kebijakan Ekonomi Hijau Dan Rendah Karbon', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 192000000, 'April 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket Dokumen', 'menyediakan dukungan teknis dalam penyusunan Rencana Kerja Pembangunan Ekonomi Hijau dan Rendah Karbon Tahun 2026', '1. Pendidikan minimal Magister (S-2) di bidang Ilmu Lingkungan/Geospasial 2. Memiliki pengalaman minimal 3 tahun dalam isu ekonomi hijau, pembangunan rendah karbon, pembangunan berketahanan iklim, atau perencanaan pembangunan. 3. Memiliki kemampuan analisis kebijakan, penyusunan dokumen teknis, dan penulisan laporan, dibuktikan dengan kontrak kerja/surat referensi pekerjaan; 4. Memiliki kemampuan analisis dan monitoring ketercapaian kebijakan pemerintah, dibuktikan dengan kontrak kerja/surat referensi pekerjaan; 5. Memiliki pengalaman dengan berkoordinasi dengan mitra pembangunan terkait dengan pembangunan rendah karbon dan berketahanan iklim (PRKBI) secara internal maupun external seperti (UN Agencies, JICA, GIZ, WRI, DFAT/Mitra Pembangunan), dibuktikan dengan kontrak kerja/surat referensi pekerjaan; 6. Memiliki pengalaman terlibat dalam penyusunan kajian terkait dengan kebijakan Pembangunan Rendah Karbon/Pembangunan Berketahanan Iklim, dibuktikan dengan publikasi; 7. Memiliki publikasi berupa artikel dan/atau tulisan blog yang membahas isu pembangunan rendah karbon dan ketahanan terhadap perubahan iklim, dibuktikan dengan publikasi; 8. Memiliki keterampilan dalam analisis data, baik tabular maupun spasial menggunakan GIS, serta cakap dalam presentasi dan penulisan laporan, dibuktikan melalui dibuktikan dengan sertifikat atau dengan dokumen referensi kontrak kerja atau hasil tulisan/laporan sebelumnya', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2835543);
