INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66523575', 66523575, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN PENYUSUNAN KAJIAN PENGUATAN KLHS RPJMD PADA KEGIATAN GLOBAL ENVIRONMENT FACILITY - SUSTAINABLE CITIES IMPACT PROJECT (GEF-SCIP)', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 185000000, 'April 2026', 'APBN - HIBAH LUAR NEGERI (I)', 1, 1, '1 Paket', 'Ruang lingkup Jasa Konsultan Penyusunan Kajian Penguatan KLHS RPJMD Kegiatan GEF-SCIP meliputi: Menyiapkan laporan analisis kebijakan KLHS RPJMD. Analisis termasuk: Analisis kesesuaian Permendagri 7/2018 dengan kebijakan terkait KLHS lainnya Analisis kelembagaan dan tata kelola KLHS RPJMD Analisis kebutuhan revisi atau penguatan substansi Permendagri baru Menyiapkan bahan paparan, brief notes, dan data yang dibutuhkan terkait dengan Penguatan Kebijakan KLHS RPJMD;', 'Pendidikan minimal Magister (S-2) di bidang lingkungan hidup, kehutanan, pengelolaan sumber daya alam; Memiliki kompetensi sesuai bidang yang dipersyaratkan dibuktikan dengan ijazah jenjang pendidikan, sertifikat keahlian/teknis, dan/atau sertifikat pelatihan/kursus; Memiliki pengetahuan dalam penyusunan KLHS, khususnya KLHS RPJMD, dibuktikan dengan sertifikat pelatihan penyusunan KLHS RPJMD; Memiliki pengalaman kerja minimal 5 (lima) tahun di bidang pembangunan daerah, perencanaan wilayah, lingkungan hidup, pengelolaan sumber daya alam, atau bidang lain yang relevan; Memiliki keterampilan dalam analisis data, baik tabular maupun spasial, serta cakap dalam presentasi dan penulisan laporan, dibuktikan melalui pengalaman kerja (cv), pengalaman proyek dan/atau refrensi kerja; Memiliki kemampuan dan pengalaman dalam mengumpulkan dan mengolah data yang dihasilkan dari kegiatan Focus Group Discussion (FGD), dibuktikan melalui pengalaman kerja (cv), pengalaman proyek dan/atau refrensi kerja; Memiliki NPWP dan telah memenuhi kewajiban perpajakan tahun pajak terakhir (SPT Tahunan PPh); Tidak sedang dimasukkan dalam daftar hitam konsultan di lingkungan Bappenas; Dapat menerima sistem pembayaran gaji sesuai dengan peraturan yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2835767);
