INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66523922', 66523922, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Penyusunan Kajian Analisis Integrasi Kebijakan Pembangunan Rendah Karbon', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 216000000, 'April 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket Dokumen', 'mendukung pengembangan dan/atau penguatan kebijakan Pembangunan Rendah Karbon (PRK) di tingkat Nasional dan Daerah untuk mendorong implementasi serta pencapaian target penurunan intensitas emisi Gas Rumah Kaca.', '1. Pendidikan minimal magister (S2) di bidang Teknik Geodesi dan Geomatika, serta memiliki kompetensi sesuai bidang yang dipersyaratkan dibuktikan dengan ijazah jenjang pendidikan, dan/atau sertifikat pelatihan/kursus; 2. Memiliki pengalaman minimum 4 (empat) tahun di bidang sumber daya alam, lingkungan hidup/perubahan iklim, dan/atau pembangunan rendah karbon dan berketahanan iklim baik di lingkungan pemerintah maupun swasta; 3. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 2 (dua) tahun terakhir baik di lingkungan pemerintah maupun non-pemerintah yang bergerak pada bidang lingkungan dan/atau sumber daya alam. 4. Memiliki pengalaman paling kurang 1 (satu) pekerjaan sejenis (jenis pekerjaan, kompleksitas pekerjaan, metodologi, teknologi, atau karakteristik lainnya yang bisa menggambarkan kesamaan); 5. Memiliki pengalaman berkoordinasi dengan mitra pembangunan terkait dengan Pembangunan Rendah Karbon dan Berketahanan Iklim (UN Agencies, UK-FCDO, GIZ, DFAT, World Bank, dll), dibuktikan dengan kontrak kerja/ surat referensi pekerjaan; 6. Memiliki kemampuan menulis yang terbukti melalui karya berupa buku/ jurnal/ publikasi/ paper di bidang pembangunan rendah karbon dan berketahanan iklim; 7. Memiliki keterampilan dalam analisis data, baik tabular maupun spasial, serta cakap dalam presentasi dan penulisan laporan, dibuktikan dengan kontrak kerja/ surat referensi pekerjaan; 8. Memiliki kemampuan dan pengalaman dalam mengumpulkan dan mengolah data yang dihasilkan dari kegiatan Focus Group Discussion (FGD), dengan kontrak kerja/ surat referensi pekerjaan; 9. Memiliki pemahaman serta pengalaman terhadap sistem dan proses perencanaan pembangunan nasional, khususnya di bidang lingkungan hidup, dibuktikan dengan kontrak kerja/ surat referensi pekerjaan;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2835976);
